import{_ as o,o as t,c as a,a4 as l}from"./chunks/framework.DzJZdBQK.js";const _=JSON.parse('{"title":"写作课作业-099","description":"","frontmatter":{"date":"2020-11-03T00:03:23","title":"写作课作业-099","categories":["写作","作业","一年顶十年"],"tags":["写作","作业","一年顶十年"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/099.md","filePath":"posts/homework/099.md"}'),p={name:"posts/homework/099.md"};function r(c,e,s,i,n,u){return t(),a("div",null,[...e[0]||(e[0]=[l('<blockquote><p>《一年顶十年》之《学霸 如何加速成为某个领域的高手？》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><blockquote><p>观念影响行为，行为影响结果。观念建设也是行动，而且是最重要的行动之一。</p></blockquote><blockquote><p>需求是最好的老师。对所学的东西又强烈的需求，效果就很不一样。</p></blockquote><blockquote><p>尽早进入实战，并不是急于求成，而是让自己在行动中得到反馈，让自己学得更好，更能解决时间问题。</p></blockquote><blockquote><p>由于经常把自己“掏空”，我会持续处于“饥渴”状态，学习的欲望非常强烈，学习的效果确实很好。</p></blockquote><blockquote><p>买经验，是必须做的事情，这样可以少走很多弯路，加速自己的进步。</p></blockquote><blockquote><p>报贵的班，课程质量更高，也会更重视，能结交更优秀的人，可以学习别人的运营方式。</p></blockquote><blockquote><p>一段时间内集中训练</p></blockquote><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>自己在开发的时候，其实经常会发现问题不知道怎么处理，于是在网上除了搜索就是搜索，如果搜索了一些文章也没得到解决的时候，开始会有些沮丧，但之后反而能更静下心来思考问题，或是换个角度思考，把自己的“饥渴”状态给激发出来，而后会处理掉这个问题，并能总结出一些新的经验。</p><p>在技术上自己没有进过大厂，见识的东西就是比较少，于是在极客时间购买了不少课程，有些课程的内容就可以直接应用到工作中，或是做一些参考关联。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',19)])])}const d=o(p,[["render",r]]);export{_ as __pageData,d as default};
